SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
START TRANSACTION;
SET time_zone = "+00:00";
SET NAMES utf8mb4;
DROP TABLE IF EXISTS message, notification, transaction, commentairesevaluations, annoncebesointransport, annoncecolistransport, utilisateur;
CREATE TABLE utilisateur (ID int NOT NULL AUTO_INCREMENT, Nom varchar(50), Prenom varchar(50), Email varchar(100), MotDePasse varchar(255), NumeroTelephone varchar(20), Adresse text, Role enum('expediteur','livreur') DEFAULT 'expediteur', Piece_identite varchar(255), rib varchar(255), PRIMARY KEY(ID), UNIQUE KEY Email(Email)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE annoncecolistransport (ID int NOT NULL AUTO_INCREMENT, UtilisateurID int, PointDepart varchar(100), Destination varchar(100), DescriptionColis text, PoidsColis decimal(10,2), DateDepart date, DateArriveePrevue date, PrixPropose decimal(10,2), Statut enum('actif','annule','termine') DEFAULT 'actif', hauteur decimal(10,2) NOT NULL DEFAULT 0, largeur decimal(10,2) NOT NULL DEFAULT 0, longueur decimal(10,2) NOT NULL DEFAULT 0, PRIMARY KEY(ID), KEY UtilisateurID(UtilisateurID), CONSTRAINT annoncecolistransport_ibfk_1 FOREIGN KEY(UtilisateurID) REFERENCES utilisateur(ID) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE annoncebesointransport (ID int NOT NULL AUTO_INCREMENT, UtilisateurID int, PointDepartSouhaite varchar(100), DestinationSouhaitee varchar(100), DescriptionColis text, PoidsColis decimal(10,2), DateLimiteEnvoi date, Budget decimal(10,2), Statut enum('actif','en attente de payement','termine') DEFAULT 'actif', nombres_de_colis int NOT NULL DEFAULT 1, livreur_id int DEFAULT NULL, is_read tinyint(1) DEFAULT 0, PhotoColis varchar(255) DEFAULT NULL, PRIMARY KEY(ID), KEY UtilisateurID(UtilisateurID), KEY livreur_id(livreur_id), CONSTRAINT annoncebesointransport_ibfk_1 FOREIGN KEY(UtilisateurID) REFERENCES utilisateur(ID) ON DELETE CASCADE, CONSTRAINT annoncebesointransport_ibfk_2 FOREIGN KEY(livreur_id) REFERENCES utilisateur(ID) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE transaction (ID int NOT NULL AUTO_INCREMENT, AnnonceColisTransportID int DEFAULT NULL, AnnonceBesoinTransportID int DEFAULT NULL, UtilisateurID int DEFAULT NULL, PrixConvenu decimal(10,2), StatutTransaction enum('en_attente_validation','en_attente_paiement','paye','en_livraison','en_cours','termine','annule') DEFAULT 'en_attente_validation', livreur_id int DEFAULT NULL, PRIMARY KEY(ID), KEY AnnonceColisTransportID(AnnonceColisTransportID), KEY AnnonceBesoinTransportID(AnnonceBesoinTransportID), KEY UtilisateurID(UtilisateurID), KEY livreur_id(livreur_id), CONSTRAINT transaction_ibfk_1 FOREIGN KEY(AnnonceColisTransportID) REFERENCES annoncecolistransport(ID) ON DELETE SET NULL, CONSTRAINT transaction_ibfk_2 FOREIGN KEY(AnnonceBesoinTransportID) REFERENCES annoncebesointransport(ID) ON DELETE SET NULL, CONSTRAINT transaction_ibfk_3 FOREIGN KEY(UtilisateurID) REFERENCES utilisateur(ID) ON DELETE SET NULL, CONSTRAINT transaction_ibfk_4 FOREIGN KEY(livreur_id) REFERENCES utilisateur(ID) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE notification (ID int NOT NULL AUTO_INCREMENT, UtilisateurID int NOT NULL, TransactionID int DEFAULT NULL, Titre varchar(120) NOT NULL, Message text NOT NULL, IsRead tinyint(1) NOT NULL DEFAULT 0, CreatedAt datetime NOT NULL DEFAULT current_timestamp(), PRIMARY KEY(ID), KEY UtilisateurID(UtilisateurID), KEY TransactionID(TransactionID), CONSTRAINT notification_ibfk_1 FOREIGN KEY(UtilisateurID) REFERENCES utilisateur(ID) ON DELETE CASCADE, CONSTRAINT notification_ibfk_2 FOREIGN KEY(TransactionID) REFERENCES transaction(ID) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE message (ID int NOT NULL AUTO_INCREMENT, TransactionID int NOT NULL, SenderID int NOT NULL, Contenu text NOT NULL, CreatedAt datetime NOT NULL DEFAULT current_timestamp(), PRIMARY KEY(ID), KEY TransactionID(TransactionID), KEY SenderID(SenderID), CONSTRAINT message_ibfk_1 FOREIGN KEY(TransactionID) REFERENCES transaction(ID) ON DELETE CASCADE, CONSTRAINT message_ibfk_2 FOREIGN KEY(SenderID) REFERENCES utilisateur(ID) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE commentairesevaluations (ID int NOT NULL AUTO_INCREMENT, UtilisateurEmetteurID int DEFAULT NULL, UtilisateurConcernedID int DEFAULT NULL, ContenuCommentaire text, NoteAttribuee int, DateEvaluation datetime DEFAULT current_timestamp(), PRIMARY KEY(ID)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
